mapper.select:
SELECT a.MOIM_ID ,a.MOIM_TITLE ,a.MOIM_DSCR ,a.MOIM_START_DT ,a.MOIM_END_DT ,d.USER_NM ,COALESCE(v.VISIT_CNT, 0) AS VISIT_CNT ,a.MAX_MEMBER ,COALESCE(m.MEMBER_CNT, 0) AS MEMBER_CNT ,c.CATE_CD ,c.CATE_NM ,e.AVG_SCORE FROM TB_TRMA_MOIM_LIST a LEFT JOIN TB_TRMA_USER_INFO d ON a.CREATE_USER = d.USER_ID LEFT JOIN ( SELECT MOIM_ID, COUNT(USER_ID) AS MEMBER_CNT FROM TB_TRMA_MOIM_MEMBER GROUP BY MOIM_ID ) m ON a.MOIM_ID = m.MOIM_ID LEFT JOIN ( SELECT MOIM_ID, COUNT(VISIT_ID) AS VISIT_CNT FROM TB_TRMA_MOIM_VISIT_H GROUP BY MOIM_ID ) v ON a.MOIM_ID = v.MOIM_ID LEFT JOIN ( SELECT e.MOIM_ID, GROUP_CONCAT(e.CATE_CD ORDER BY e.CATE_CD) AS CATE_CD, GROUP_CONCAT(f.CMM_CM_NM ORDER BY f.CMM_CM_NM) AS CATE_NM FROM TB_TRMA_MOIM_CATE e LEFT JOIN TB_TRMA_CMM_CD_D f ON e.CATE_CD = f.CMM_CDV AND f.CMM_CD_ID = 'CATE_ID' AND f.USE_YN = 'Y' GROUP BY e.MOIM_ID ) c ON a.MOIM_ID = c.MOIM_ID LEFT JOIN ( SELECT MOIM_ID, AVG(REVIEW_SCORE) AS AVG_SCORE FROM TB_TRMA_MOIM_REVIEW GROUP BY MOIM_ID ) e ON a.MOIM_ID = e.MOIM_ID WHERE a.USE_YN = 'Y' AND a.MOIM_START_DT > NOW()
AND ( a.MOIM_TITLE LIKE CONCAT('%', #{keyword}, '%') OR a.MOIM_DSCR LIKE CONCAT('%', #{keyword}, '%') )
AND c.CATE_CD = #{cateCd}
LIMIT 10 OFFSET #{offset}

mapper.update:
UPDATE TB_TRMA_MOIM_MEMBER
SET STATE_CD = #{stateCd}
    ,UPDATE_USER = #{userId}
    ,UPDATE_DT = CURRENT_TIMESTAMP
WHERE MOIM_ID = #{moimId}
    AND USER_ID = #{targetUserId}

mapper.delete:
DELETE FROM TB_TRMA_MOIM_MEMBER
WHERE MOIM_ID = #{moimId}
    AND USER_ID = #{targetUserId}
